"use client";

import { useEffect, useRef, useState } from "react";
import { AlertTriangle, ArrowLeft, ArrowRight, BookOpen, Bot, Boxes, Check, CheckCircle2, ChevronDown, Clapperboard, Copy, Film, Focus, ImagePlus, Library, Loader2, MapPinned, Menu, MonitorPlay, PanelLeftClose, PanelLeftOpen, PanelRightClose, PanelRightOpen, Plus, RotateCcw, Search, Settings2, ShieldCheck, Sparkles, Star, Users, XCircle } from "lucide-react";
import { ProjectAssistant } from "@/components/project-assistant";
import { Button } from "@/components/ui/button";
import { CommandDialog, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList, CommandShortcut } from "@/components/ui/command";
import { Progress } from "@/components/ui/progress";
import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from "@/components/ui/resizable";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Toaster, toast } from "sonner";
import { SCAEVA_STYLE, SCAEVA_STYLE_NEGATIVE, activeCharacterVersion, compilePrompt, findPreviousShot, scaevaCharacterDefaults, sceneIdForShot, shotCode, type AssetRef, type CharacterBible, type CharacterVersion, type ContinuityAnalysis, type LocationBible, type ProductionProject as Project, type ProductionShot as Shot, type PropBible, type ReferenceKind, type Take, type TransitionType } from "@/lib/production";
import type { AssistantAction } from "@/lib/assistant-types";
import { configuredExtensionId, sanitizedGenerationDiagnostic, saveExtensionId, startBrowserGeneration, testBrowserBridge, type BridgeDiagnostic, type BridgeStatus } from "@/lib/browser-bridge-client";
import { validateGenerationPackage, type GenerationPackageV1, type GenerationPreflight } from "@/lib/generation-package";

const legacyStyle = "Cinematográfico, movimento natural, luz suave e composição cuidada.";
const referenceGroups: {kind:ReferenceKind;label:string;hint:string}[] = [
  {kind:"OFFICIAL_IDENTITY",label:"Official identity",hint:"Prioridade máxima"},
  {kind:"FACE",label:"Face",hint:"Close-ups"},
  {kind:"HAIR",label:"Hair",hint:"Forma e volume"},
  {kind:"FULL_BODY",label:"Full body",hint:"Proporções"},
  {kind:"COSTUME",label:"Costume",hint:"Roupa e materiais"},
  {kind:"ACTION",label:"Action references",hint:"Movimento"},
  {kind:"ARCHIVE",label:"Older / archive",hint:"Nunca usado em AUTO"},
];

const makeShot = (id:string, sceneNumber:number, shotNumber:number, title="Novo shot"):Shot => ({
  id,title,sceneNumber,shotNumber,action:"",camera:"Auto",duration:"4",durationMode:"AUTO",
  continuity:"Preservar identidade, cenário, direção do movimento e objetos visíveis.",
  negative:"No identity drift, no duplicated objects, no anatomy errors, no text or watermark.",
  assets:[],queued:false,status:"DRAFT",qualityTarget:"STANDARD",preferredProvider:"vibes",
  startFrameMode:"PREVIOUS_LAST_FRAME",characterVersionIds:[],locationVersionId:"",
  transitionType:"AUTO",autoMode:true,takes:[],
});

const initial:Project = {
  title:"SCAEVA",url:"",style:SCAEVA_STYLE,styleNegative:SCAEVA_STYLE_NEGATIVE,budgetMode:"BALANCED",
  storyRules:"Grounded historical drama. Preserve chronology and character motivation.",
  continuityRules:"Approved last frame is canonical. Preserve screen direction, visible props, wardrobe and lighting.",
  characters:scaevaCharacterDefaults(),locations:[],
  props:[{id:"prop-father-coin",name:"Father's Coin",description:"Dull old coin worn by Scaeva on one leather cord.",rules:"Exactly one coin. Owner: Scaeva. Visible only when motivated.",status:"ACTIVE"}],
  scenes:[makeShot("shot-04-07",4,7,"The Hand")],
};

function normalize(raw:Partial<Project>):Project {
  const rawShots=Array.isArray(raw.scenes)&&raw.scenes.length?raw.scenes:initial.scenes;
  const characters=(Array.isArray(raw.characters)&&raw.characters.length?raw.characters:scaevaCharacterDefaults()).map((character)=>{
    const versions=(character.versions||[]).map((version,index)=>({...version,label:version.label==="Official"?`V${index+1}`:version.label,active:version.active??index===character.versions.length-1,references:(version.references||[]).map((asset,assetIndex)=>({...asset,kind:asset.kind||(assetIndex===0?"OFFICIAL_IDENTITY":"ACTION")}))}));
    const active=versions.find((version)=>version.id===character.activeVersionId)||versions.find((version)=>version.active)||versions.at(-1);
    return {...character,versions:versions.map((version)=>({...version,active:version.id===active?.id})),activeVersionId:active?.id,knownFailures:character.knownFailures||[]};
  });
  return {...initial,...raw,title:!raw.title||raw.title==="O meu próximo filme"?"SCAEVA":raw.title,style:!raw.style||raw.style===legacyStyle?SCAEVA_STYLE:raw.style,styleNegative:raw.styleNegative||SCAEVA_STYLE_NEGATIVE,storyRules:raw.storyRules||initial.storyRules,continuityRules:raw.continuityRules||initial.continuityRules,characters,locations:Array.isArray(raw.locations)?raw.locations:[],props:Array.isArray(raw.props)?raw.props:initial.props,scenes:rawShots.map((item,index)=>({...makeShot(item.id,item.sceneNumber||1,item.shotNumber||index+1,item.title),...item,durationMode:item.durationMode||"MANUAL",transitionType:item.transitionType||"AUTO",autoMode:item.autoMode??true,assets:item.assets||[],takes:item.takes||[],characterVersionIds:item.characterVersionIds||[]}))};
}

async function request<T=any>(url:string,options?:RequestInit):Promise<T>{const response=await fetch(url,options);const payload:any=await response.json().catch(()=>null);if(!response.ok){const error=new Error(payload?.error||"Não foi possível concluir.") as Error&{details?:unknown};error.details=payload;throw error;}return payload as T;}

export default function PromptDirector(){
  const [project,setProject]=useState<Project>(initial);
  const [selectedId,setSelectedId]=useState(initial.scenes[0].id);
  const [view,setView]=useState<"production"|"bible">("production");
  const [bibleTab,setBibleTab]=useState("overview");
  const [loading,setLoading]=useState(true);
  const [busy,setBusy]=useState(false);
  const [dirty,setDirty]=useState(false);
  const [saveState,setSaveState]=useState<"saved"|"saving"|"error">("saved");
  const [collapsed,setCollapsed]=useState(false);
  const [mobileNav,setMobileNav]=useState(false);
  const [palette,setPalette]=useState(false);
  const [focusMode,setFocusMode]=useState(false);
  const [inspectorOpen,setInspectorOpen]=useState(true);
  const [assistantOpen,setAssistantOpen]=useState(false);
  const [providerSettingsOpen,setProviderSettingsOpen]=useState(false);
  const [assistantCharacterId,setAssistantCharacterId]=useState<string>();
  const [analysisWarning,setAnalysisWarning]=useState<string>();
  const [generationPreflight,setGenerationPreflight]=useState<GenerationPreflight>();
  const [generationDiagnostic,setGenerationDiagnostic]=useState<unknown>();
  const storyboardInput=useRef<HTMLInputElement>(null);
  const continuityInput=useRef<HTMLInputElement>(null);
  const bridgeDisconnect=useRef<(()=>void)|null>(null);
  const shot=project.scenes.find((item)=>item.id===selectedId)||project.scenes[0];
  const shotIndex=project.scenes.findIndex((item)=>item.id===shot.id);
  const previousResolution=findPreviousShot(project,sceneIdForShot(shot),shot.id);
  const previous=previousResolution.shot;
  const previousTake=previousResolution.approvedTake;
  const continuityFrame=shot.startFrameMode==="CUSTOM"?shot.assets.find((asset)=>asset.kind==="START_FRAME"):previousTake?.finalFrame;
  const approved=project.scenes.filter((item)=>item.status==="APPROVED").length;
  const progress=Math.round(approved/project.scenes.length*100);

  useEffect(()=>{
    setCollapsed(localStorage.getItem("pd-sidebar")==="collapsed");
    const inspectorPreference=localStorage.getItem("pd-inspector");
    setInspectorOpen(inspectorPreference?inspectorPreference!=="closed":innerWidth>=1500);
    request<Project|null>("/api/studio").then((saved)=>{if(saved){const next=normalize(saved);setProject(next);setSelectedId(next.scenes[0].id);}}).catch(()=>toast.error("Não foi possível carregar o projeto.")).finally(()=>setLoading(false));
    testBrowserBridge().catch(()=>undefined);
  },[]);
  useEffect(()=>{
    function shortcut(event:KeyboardEvent){
      if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==="k"){event.preventDefault();setPalette((open)=>!open);}
      if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==="j"){event.preventDefault();setAssistantOpen((open)=>!open);}
      const typing=(event.target as HTMLElement)?.matches("input, textarea, [contenteditable=true]");
      if(!typing&&!event.metaKey&&!event.ctrlKey&&event.key.toLowerCase()==="f"){event.preventDefault();setFocusMode((value)=>!value);}
    }
    addEventListener("keydown",shortcut);return()=>removeEventListener("keydown",shortcut);
  },[]);
  useEffect(()=>{
    if(!dirty||loading)return;
    setSaveState("saving");
    const timer=setTimeout(()=>request("/api/studio",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(project)}).then(()=>{setDirty(false);setSaveState("saved");}).catch(()=>setSaveState("error")),900);
    return()=>clearTimeout(timer);
  },[project,dirty,loading]);
  useEffect(()=>{
    const active=[...shot.takes].reverse().find((take)=>take.generationId&&!["REVIEW","APPROVED","REJECTED","FAILED","PAUSED","AUTH_REQUIRED"].includes(take.status));
    if(!active?.generationId)return;
    const timer=setInterval(()=>request<{status:Take["status"];progress:number;outputUrl?:string;outputAsset?:AssetRef;error?:string}>(`/api/generations?id=${active.generationId}`).then((generation)=>{
      change({scenes:project.scenes.map((item)=>item.id===shot.id?{...item,status:generation.status==="REVIEW"?"REVIEW":generation.status==="FAILED"?"FAILED":"GENERATING",takes:item.takes.map((take)=>take.id===active.id?{...take,status:generation.status,progress:generation.progress,outputUrl:generation.outputUrl,outputAsset:generation.outputAsset||take.outputAsset,notes:generation.error||take.notes}:take)}:item)});
    }).catch(()=>{}),5000);
    return()=>clearInterval(timer);
  },[shot.id,shot.takes,project.scenes]);

  function change(patch:Partial<Project>){setProject((current)=>({...current,...patch}));setDirty(true);}
  function updateShot(patch:Partial<Shot>){change({scenes:project.scenes.map((item)=>item.id===shot.id?{...item,...patch}:item)});}
  async function save(nextProject=project){setSaveState("saving");try{await request("/api/studio",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(nextProject)});setDirty(false);setSaveState("saved");}catch(error){setSaveState("error");toast.error((error as Error).message);throw error;}}
  async function uploadFile(file:File,kind:string){const body=new FormData();body.append("file",file);body.append("kind",kind);return request<AssetRef>("/api/assets",{method:"POST",body});}
  async function setStoryboard(file?:File){if(!file)return;setBusy(true);try{const asset=await uploadFile(file,"STORYBOARD");updateShot({storyboard:asset,analysis:undefined,promptDraft:undefined,preparedPrompt:undefined});toast.success("Storyboard associado ao shot");}catch(error){toast.error((error as Error).message);}finally{setBusy(false);}}
  async function setManualContinuity(file?:File){if(!file)return;setBusy(true);try{const asset=await uploadFile(file,"START_FRAME");updateShot({assets:[...shot.assets.filter((item)=>item.kind!=="START_FRAME"),asset],startFrameMode:"CUSTOM",analysis:undefined,promptDraft:undefined,preparedPrompt:undefined});toast.success("Continuidade manual adicionada");}catch(error){toast.error((error as Error).message);}finally{setBusy(false);}}
  async function prepareShot(){if(!shot.storyboard){toast.error("Adiciona o storyboard primeiro.");return;}setBusy(true);setAnalysisWarning(undefined);setGenerationPreflight(undefined);try{const result=await request<{analysis:ContinuityAnalysis;prompt:string;warningCode?:string;warning?:string}>("/api/analyze",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({project,shotId:shot.id})});updateShot({analysis:result.analysis,promptDraft:result.prompt,preparedPrompt:result.prompt,status:result.analysis.critical.length?"DRAFT":"READY"});setAnalysisWarning(result.warningCode);if(result.warning)toast.warning(result.warning);else toast.success("Shot preparado com análise de IA.");}catch(error){toast.error((error as Error).message);}finally{setBusy(false);}}
  async function prepareGeneration(){
    if(!shot.preparedPrompt){toast.error("Prepara o shot primeiro.");return;}
    setBusy(true);setGenerationDiagnostic(undefined);setGenerationPreflight(undefined);
    try{
      await save();
      const generation=await request<{id:string;takeId:string;provider:string;status:Take["status"];progress:number;prompt:string;createdAt:string;generationPackage:GenerationPackageV1;preflight:GenerationPreflight}>("/api/generations",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({projectId:"main",shotId:shot.id,provider:shot.preferredProvider,transport:"BROWSER_EXTENSION"})});
      setGenerationPreflight(generation.preflight);
      const packageValidation=validateGenerationPackage(generation.generationPackage);
      if(!packageValidation.success)throw Object.assign(new Error("Generation package invalid"),{details:sanitizedGenerationDiagnostic(generation.generationPackage,packageValidation)});
      const bridge=await testBrowserBridge();
      if(!bridge.ok||bridge.status==="disconnected")throw new Error("PromptDirector Bridge not detected.");
      const take:Take={id:generation.takeId,generationId:generation.id,provider:generation.provider,model:"",status:"PREPARING",bridgeStatus:"preparing",progress:0,prompt:generation.prompt,createdAt:generation.createdAt,externalActionUrl:generation.generationPackage.project.vibesProjectUrl,rejectionReasons:[],notes:"PACKAGE READY"};
      updateShot({queued:true,status:"GENERATING",takes:[...shot.takes,take]});
      bridgeDisconnect.current?.();
      bridgeDisconnect.current=startBrowserGeneration(generation.generationPackage,(message)=>{
        const status:Take["status"]=message.status==="completed"?"REVIEW":message.status==="failed"?"FAILED":message.status==="auth_required"?"AUTH_REQUIRED":message.status==="disconnected"?"PAUSED":"GENERATING";
        const progressMap:Partial<Record<BridgeStatus,number>>={preparing:5,opening_vibes:10,waiting_for_vibes:15,auth_required:15,uploading_references:30,configuring:40,submitting:50,generating:60,processing:80,completed:100,failed:0,disconnected:0};
        setProject((current)=>({...current,scenes:current.scenes.map((item)=>item.id===shot.id?{...item,status:status==="REVIEW"?"REVIEW":status==="FAILED"?"FAILED":status==="AUTH_REQUIRED"?"PAUSED":"GENERATING",takes:item.takes.map((itemTake)=>itemTake.id===take.id?{...itemTake,status,bridgeStatus:message.status,progress:progressMap[message.status]??itemTake.progress,outputUrl:message.outputUrl,notes:message.message||message.stage}:itemTake)}:item)}));setDirty(true);
        request("/api/generations",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:generation.id,takeId:generation.takeId,bridgeStatus:message.status,outputUrl:message.outputUrl,error:message.message})}).catch(()=>toast.error("O estado do bridge não foi guardado."));
        if(message.type==="PD_ERROR")setGenerationDiagnostic({stage:message.stage,errorCode:message.errorCode,message:message.message,details:message.details});
        if(message.status==="auth_required")toast.warning("Meta Vibes requires login.");
        if(message.status==="failed")toast.error(message.message||"Meta Vibes generation failed.");
        if(message.stage==="GENERATION_SUBMITTED")toast.success("Geração iniciada no Meta Vibes.");
        if(message.status==="completed")toast.success("Vídeo concluído no Meta Vibes.");
      },{connection:bridge.connection,extensionId:configuredExtensionId()});
      toast.success("PromptDirector Bridge iniciou o Meta Vibes");
    }catch(error){const detailed=error as Error&{details?:any};if(detailed.details){setGenerationDiagnostic(detailed.details);const server=detailed.details;setGenerationPreflight(server?.missing?{valid:false,ready:false,environmentSource:null,checks:[],warnings:server.warnings||[],missing:server.missing||[],invalid:server.invalid||[],unresolvedAssets:server.unresolvedAssets||[]}:undefined);}toast.error(detailed.message);}finally{setBusy(false);}
  }
  async function frameFromVideo(file:File){const url=URL.createObjectURL(file);const player=document.createElement("video");player.src=url;player.muted=true;player.playsInline=true;await new Promise<void>((resolve,reject)=>{player.onloadedmetadata=()=>resolve();player.onerror=()=>reject(new Error("Vídeo inválido."));});player.currentTime=Math.max(0,player.duration-0.08);await new Promise<void>((resolve,reject)=>{player.onseeked=()=>resolve();player.onerror=()=>reject(new Error("Não foi possível extrair o frame."));});const canvas=document.createElement("canvas");canvas.width=player.videoWidth;canvas.height=player.videoHeight;canvas.getContext("2d")!.drawImage(player,0,0);const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob((value)=>value?resolve(value):reject(new Error("Não foi possível criar o frame.")),"image/png"));URL.revokeObjectURL(url);return new File([blob],`${shotCode(shot)}-last-frame.png`,{type:"image/png"});}
  async function approveVideo(file?:File){if(!file)return;setBusy(true);try{const [videoAsset,frameFile]=await Promise.all([uploadFile(file,"GENERATED_VIDEO"),frameFromVideo(file)]);const finalFrame=await uploadFile(frameFile,"LAST_FRAME");const take:Take={id:crypto.randomUUID(),provider:shot.preferredProvider,model:"",status:"APPROVED",prompt:shot.preparedPrompt||compilePrompt(project,shot,shot.preferredProvider),createdAt:new Date().toISOString(),outputAsset:videoAsset,finalFrame,rejectionReasons:[],notes:""};const scenes=project.scenes.map((item,index)=>index===shotIndex?{...item,takes:[...item.takes,take],approvedTakeId:take.id,status:"APPROVED" as const,queued:false}:index===shotIndex+1?{...item,startFrameMode:"PREVIOUS_LAST_FRAME" as const,analysis:undefined,preparedPrompt:undefined}:item);const approvedProject={...project,scenes};setProject(approvedProject);await save(approvedProject);toast.success(`Shot ${shotCode(shot)} aprovado. Último frame ligado ao próximo.`);}catch(error){toast.error((error as Error).message);}finally{setBusy(false);}}
  function addShot(){const last=project.scenes.at(-1)!;const next=makeShot(crypto.randomUUID(),last.sceneNumber,last.shotNumber+1);change({scenes:[...project.scenes,next]});setSelectedId(next.id);}
  function toggleCharacter(character:CharacterBible){const version=activeCharacterVersion(character);if(!version)return;const related=character.versions.map((item)=>item.id);const clean=shot.characterVersionIds.filter((id)=>!related.includes(id));updateShot({characterVersionIds:shot.characterVersionIds.some((id)=>related.includes(id))?clean:[...clean,version.id],analysis:undefined,preparedPrompt:undefined});}
  function navigate(next:"production"|"bible",tab?:string){setView(next);if(tab)setBibleTab(tab);setPalette(false);setMobileNav(false);}
  function selectShot(id:string){setSelectedId(id);setView("production");setPalette(false);}
  function toggleSidebar(){setCollapsed((value)=>{localStorage.setItem("pd-sidebar",value?"expanded":"collapsed");return !value;});}
  function toggleInspector(){setInspectorOpen((value)=>{localStorage.setItem("pd-inspector",value?"closed":"open");return !value;});}
  function applyAssistantAction(action:AssistantAction){
    if(action.type==="OPEN_CHARACTER_REFERENCES"){setAssistantCharacterId(action.payload?.characterId);setView("bible");setBibleTab("characters");setAssistantOpen(false);return;}
    if(action.type==="SELECT_LOCATION"){setView("bible");setBibleTab("locations");setAssistantOpen(false);return;}
    const targetId=action.payload?.shotId||shot.id;
    if(action.type==="LINK_PREVIOUS_SHOT"){change({scenes:project.scenes.map((item)=>item.id===targetId?{...item,startFrameMode:"PREVIOUS_LAST_FRAME",analysis:undefined,preparedPrompt:undefined}:item)});toast.success("Previous shot link prepared");return;}
    if(action.type==="REPLACE_PROMPT"&&action.payload?.prompt){change({scenes:project.scenes.map((item)=>item.id===targetId?{...item,promptDraft:action.payload!.prompt,preparedPrompt:action.payload!.prompt}:item)});toast.success("Current prompt replaced");}
  }

  const crumb=view==="bible"?`${project.title} / Project Bible / ${bibleTab.replace(/^./,(letter)=>letter.toUpperCase())}`:`${project.title} / Scene ${String(shot.sceneNumber).padStart(2,"0")} / Shot ${shotCode(shot)}`;
  return <div className={`app-shell ${collapsed?"sidebar-collapsed":""} ${focusMode?"focus-mode":""} ${mobileNav?"mobile-nav-open":""} ${assistantOpen?"assistant-open":""}`}>
    <Toaster theme="dark" richColors/>
    <ProviderSettingsSheet open={providerSettingsOpen} onClose={()=>setProviderSettingsOpen(false)}/>
    <aside className="app-sidebar">
      <div className="sidebar-brand"><button className="brand" onClick={()=>navigate("production")}><span><Clapperboard/></span><b>PromptDirector</b></button><button className="collapse-sidebar" onClick={toggleSidebar} aria-label={collapsed?"Expandir sidebar":"Recolher sidebar"}>{collapsed?<PanelLeftOpen/>:<PanelLeftClose/>}</button></div>
      <div className="project-mini"><small>PROJECT</small><b>{project.title}</b><span>Episode 01</span><div><Progress value={progress}/><em>{approved}/{project.scenes.length}</em></div></div>
      <nav className="primary-nav">
        <button aria-label="Production" title="Production" className={view==="production"?"active":""} onClick={()=>navigate("production")}><Film/><span>Production</span></button>
        <button aria-label="Projects" title="Projects" onClick={()=>toast.info(`${project.title} é o projeto ativo.`)}><Library/><span>Projects</span></button>
        <button aria-label="Project Bible" title="Project Bible" className={view==="bible"?"active":""} onClick={()=>navigate("bible","overview")}><BookOpen/><span>Project Bible</span></button>
        <button aria-label="Scenes" title="Scenes" onClick={()=>navigate("production")}><Clapperboard/><span>Scenes</span></button>
        <button aria-label="Generations" title="Generations" onClick={()=>{const review=project.scenes.find((item)=>item.takes.length);if(review)selectShot(review.id);else navigate("production");}}><MonitorPlay/><span>Generations</span></button>
      </nav>
      <div className="sidebar-foot"><button aria-label="Settings" title="Settings" onClick={()=>setProviderSettingsOpen(true)}><Settings2/><span>Settings</span></button><small>⌘K Quick actions</small></div>
    </aside>
    <div className="app-main">
      <header className="topbar"><button className="mobile-menu" onClick={()=>setMobileNav((open)=>!open)}><Menu/></button><span className="breadcrumb">{crumb}</span><div className="top-actions"><button className="search-action" onClick={()=>setPalette(true)}><Search/><span>Search</span><kbd>⌘K</kbd></button>{view==="production"&&<button className="icon-action" onClick={()=>setFocusMode((value)=>!value)} title="Focus mode (F)"><Focus/></button>}<span className={`save-status ${saveState}`}>{saveState==="saving"?"Saving…":saveState==="error"?"Save failed":"Saved"}</span></div></header>
      {view==="bible"?<ProjectBible project={project} change={change} uploadFile={uploadFile} tab={bibleTab} setTab={setBibleTab} openCharacterId={assistantCharacterId} onCharacterSelect={setAssistantCharacterId}/>:<ProductionWorkspace project={project} shot={shot} previous={previous} continuityFrame={continuityFrame} progress={progress} busy={busy} analysisWarning={analysisWarning} generationPreflight={generationPreflight} generationDiagnostic={generationDiagnostic} storyboardInput={storyboardInput} continuityInput={continuityInput} setSelectedId={setSelectedId} addShot={addShot} updateShot={updateShot} setStoryboard={setStoryboard} setManualContinuity={setManualContinuity} toggleCharacter={toggleCharacter} prepareShot={prepareShot} prepareGeneration={prepareGeneration} approveVideo={approveVideo} inspectorOpen={inspectorOpen&&!focusMode} toggleInspector={toggleInspector} focusMode={focusMode} exitFocus={()=>setFocusMode(false)}/>}
    </div>
    <ProjectAssistant open={assistantOpen} project={project} currentShot={shot} surface={view} bibleTab={bibleTab} currentCharacterId={assistantCharacterId} onClose={()=>setAssistantOpen(false)} onBeforeSend={()=>save()} onAction={applyAssistantAction}/>
    {!assistantOpen&&<button className="assistant-launch" onClick={()=>setAssistantOpen(true)}><Bot/><span>Assistant</span><kbd>⌘J</kbd></button>}
    {mobileNav&&<button className="nav-scrim" onClick={()=>setMobileNav(false)} aria-label="Fechar navegação"/>}
    <CommandPalette open={palette} setOpen={setPalette} project={project} navigate={navigate} selectShot={selectShot} prepareShot={prepareShot}/>
  </div>;
}

function CommandPalette({open,setOpen,project,navigate,selectShot,prepareShot}:{open:boolean;setOpen:(open:boolean)=>void;project:Project;navigate:(view:"production"|"bible",tab?:string)=>void;selectShot:(id:string)=>void;prepareShot:()=>void}){
  return <CommandDialog open={open} onOpenChange={setOpen} title="PromptDirector commands" description="Navigate and search the current production."><CommandInput placeholder="Search characters, shots, locations, props…"/><CommandList><CommandEmpty>No results.</CommandEmpty><CommandGroup heading="Actions"><CommandItem onSelect={()=>navigate("production")}><Film/>Open Production<CommandShortcut>P</CommandShortcut></CommandItem><CommandItem onSelect={()=>navigate("bible","overview")}><BookOpen/>Open Project Bible</CommandItem><CommandItem onSelect={()=>{setOpen(false);prepareShot();}}><Sparkles/>Prepare current shot</CommandItem></CommandGroup><CommandGroup heading="Shots">{project.scenes.map((shot)=><CommandItem key={shot.id} value={`${shotCode(shot)} ${shot.title}`} onSelect={()=>selectShot(shot.id)}><Clapperboard/>{shotCode(shot)} — {shot.title}</CommandItem>)}</CommandGroup><CommandGroup heading="Characters">{project.characters.map((character)=><CommandItem key={character.id} onSelect={()=>navigate("bible","characters")}><Users/>{character.name}</CommandItem>)}</CommandGroup><CommandGroup heading="World">{project.locations.map((location)=><CommandItem key={location.id} onSelect={()=>navigate("bible","locations")}><MapPinned/>{location.name}</CommandItem>)}{project.props.map((prop)=><CommandItem key={prop.id} onSelect={()=>navigate("bible","props")}><Boxes/>{prop.name}</CommandItem>)}</CommandGroup></CommandList></CommandDialog>;
}

function ProductionWorkspace({project,shot,previous,continuityFrame,progress,busy,analysisWarning,generationPreflight,generationDiagnostic,storyboardInput,continuityInput,setSelectedId,addShot,updateShot,setStoryboard,setManualContinuity,toggleCharacter,prepareShot,prepareGeneration,approveVideo,inspectorOpen,toggleInspector,focusMode,exitFocus}:{project:Project;shot:Shot;previous?:Shot;continuityFrame?:AssetRef;progress:number;busy:boolean;analysisWarning?:string;generationPreflight?:GenerationPreflight;generationDiagnostic?:unknown;storyboardInput:React.RefObject<HTMLInputElement|null>;continuityInput:React.RefObject<HTMLInputElement|null>;setSelectedId:(id:string)=>void;addShot:()=>void;updateShot:(patch:Partial<Shot>)=>void;setStoryboard:(file?:File)=>void;setManualContinuity:(file?:File)=>void;toggleCharacter:(character:CharacterBible)=>void;prepareShot:()=>void;prepareGeneration:()=>void;approveVideo:(file?:File)=>void;inspectorOpen:boolean;toggleInspector:()=>void;focusMode:boolean;exitFocus:()=>void}){
  const index=project.scenes.findIndex((item)=>item.id===shot.id);const approvedTake=shot.takes.find((take)=>take.id===shot.approvedTakeId);const latestTake=shot.takes.at(-1);const previewTake=approvedTake||[...shot.takes].reverse().find((take)=>take.outputAsset||take.outputUrl);const next=project.scenes[index+1];const back=project.scenes[index-1];
  const previousInfo=findPreviousShot(project,sceneIdForShot(shot),shot.id);
  const previousFrameEmpty=previousInfo.isFirst?"Primeiro shot da sequência":previousInfo.shot?"A aguardar aprovação":`${previousInfo.expectedCode} não importado`;
  const previousFrameNote=continuityFrame&&previous?`AUTO · ${shotCode(previous)}`:previousInfo.isFirst?"Sem plano anterior":previousInfo.shot&&!previousInfo.approvedTake?"Previous shot exists but is not approved.":!previousInfo.shot?`Previous shot ${previousInfo.expectedCode} is not imported.`:"Continuidade automática";
  const showFallback=Boolean(latestTake&&["FAILED","PAUSED","AUTH_REQUIRED"].includes(latestTake.status));
  async function exportGenerationPackage(){
    if(!latestTake?.generationId)return;
    try{
      const generation=await request(`/api/generations?id=${encodeURIComponent(latestTake.generationId)}`);
      const blob=new Blob([JSON.stringify(generation,null,2)],{type:"application/json"});
      const url=URL.createObjectURL(blob);const link=document.createElement("a");link.href=url;link.download=`${shotCode(shot)}-generation-package.json`;link.click();URL.revokeObjectURL(url);
    }catch(error){toast.error((error as Error).message);}
  }
  const nav=<aside className="shot-rail"><div className="scene-summary"><small>SCENE {String(shot.sceneNumber).padStart(2,"0")}</small><strong>{progress}%</strong><Progress value={progress}/></div><div className="rail-heading"><span>SHOTS</span><button onClick={addShot}><Plus/></button></div><nav>{project.scenes.map((item)=><button key={item.id} className={item.id===shot.id?"shot-link current":"shot-link"} onClick={()=>setSelectedId(item.id)}><StatusMark status={item.status}/><span><b>{shotCode(item)}</b><small>{item.title}</small></span></button>)}</nav></aside>;
  const canvas=<main className="visual-workspace"><div className="shot-heading"><div><small>{project.title} / SCENE {String(shot.sceneNumber).padStart(2,"0")}</small><div className="shot-switcher"><button disabled={!back} onClick={()=>back&&setSelectedId(back.id)}><ArrowLeft/></button><input value={shot.title} aria-label="Nome do shot" onChange={(event)=>updateShot({title:event.target.value})}/><button disabled={!next} onClick={()=>next&&setSelectedId(next.id)}><ArrowRight/></button></div></div><div className="canvas-actions"><label className="auto-toggle"><Sparkles/>AUTO<input type="checkbox" checked={shot.autoMode} onChange={(event)=>updateShot({autoMode:event.target.checked})}/></label>{focusMode&&<button className="icon-action" onClick={exitFocus}><Focus/></button>}{!inspectorOpen&&!focusMode&&<button className="icon-action" onClick={toggleInspector} title="Abrir inspector"><PanelRightOpen/></button>}</div></div><div className="hero-visual"><UploadCard title="STORYBOARD" asset={shot.storyboard} empty="Adicionar storyboard" onClick={()=>storyboardInput.current?.click()}/><input ref={storyboardInput} hidden type="file" accept="image/png,image/jpeg,image/webp" onChange={(event)=>{setStoryboard(event.target.files?.[0]);event.target.value="";}}/></div>{latestTake&&<div className={`generation-state ${latestTake.status.toLowerCase()}`}><span><b>{latestTake.status.replaceAll("_"," ")}</b><small>Take {shot.takes.length} · {latestTake.provider}{latestTake.progress!=null?` · ${latestTake.progress}%`:""}</small></span>{showFallback&&<div className="generation-fallback"><button onClick={prepareGeneration}>RETRY AUTOMATIC</button>{latestTake.externalActionUrl&&<a href={latestTake.externalActionUrl} target="_blank" rel="noreferrer">OPEN VIBES MANUALLY</a>}<button onClick={async()=>{await navigator.clipboard.writeText(latestTake.prompt);toast.success("Prompt copiado");}}>COPY PROMPT</button><button onClick={exportGenerationPackage}>EXPORT PACKAGE</button></div>}{!showFallback&&latestTake.externalActionUrl&&<a href={latestTake.externalActionUrl} target="_blank" rel="noreferrer">OPEN META VIBES</a>}{latestTake.notes&&<em>{latestTake.notes}</em>}</div>}<div className="visual-pair"><MediaCard title="VIDEO PREVIEW" asset={previewTake?.outputAsset} sourceUrl={previewTake?.outputUrl} kind="video" empty="Ainda sem geração"/><UploadCard title="PREVIOUS LAST FRAME" asset={continuityFrame} empty={previousFrameEmpty} note={previousFrameNote} onClick={()=>continuityInput.current?.click()}/><input ref={continuityInput} hidden type="file" accept="image/png,image/jpeg,image/webp" onChange={(event)=>{setManualContinuity(event.target.files?.[0]);event.target.value="";}}/></div>{shot.status==="APPROVED"&&<div className="approved-banner"><CheckCircle2/><span><b>Shot approved</b>O último frame já está preparado para o próximo shot.</span>{next&&<Button onClick={()=>setSelectedId(next.id)}>NEXT SHOT <ArrowRight/></Button>}</div>}</main>;
  const inspector=<aside className="director-panel"><div className="panel-title"><div><small>{shotCode(shot)}</small><strong>Prepare shot</strong></div><button className="icon-action" onClick={toggleInspector} title="Fechar inspector"><PanelRightClose/></button></div><label className="field-label">O QUE ACONTECE?</label><textarea className="action-input" value={shot.action} onChange={(event)=>updateShot({action:event.target.value,analysis:undefined,preparedPrompt:undefined})} placeholder="Descreve a ação criativa deste shot…"/><div className="smart-row"><div><small>CHARACTERS</small><div className="character-chips">{project.characters.map((character)=>{const related=character.versions.map((item)=>item.id);const active=shot.characterVersionIds.some((id)=>related.includes(id));return <button key={character.id} className={active?"selected":""} onClick={()=>toggleCharacter(character)}>{active&&<Check/>}{character.name}</button>;})}</div></div><div><small>DURATION</small><Select value={shot.durationMode==="AUTO"?"AUTO":shot.duration} onValueChange={(value)=>updateShot(value==="AUTO"?{durationMode:"AUTO"}:{durationMode:"MANUAL",duration:value})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="AUTO">AUTO</SelectItem>{["4","5","6","8"].map((value)=><SelectItem key={value} value={value}>{value}s</SelectItem>)}</SelectContent></Select></div></div><Button className="prepare-button" onClick={prepareShot} disabled={busy}>{busy?<Loader2 className="spin"/>:<Sparkles/>}PREPARE SHOT<ArrowRight/></Button>{analysisWarning&&<div className="analysis-fallback"><AlertTriangle/><span><b>AI_ANALYSIS_UNAVAILABLE</b>Análise de IA indisponível. Shot preparado usando análise local.</span><button onClick={prepareShot}>Retry AI Analysis</button></div>}{shot.analysis&&<><details className="fold" open><summary><span>Continuity</span><ChevronDown/></summary><AnalysisPanel analysis={shot.analysis}/></details><details className="fold"><summary><span>References <b>{shot.analysis.references.length}</b></span><ChevronDown/></summary><div className="reference-list">{shot.analysis.references.map((item)=><div key={`${item.priority}-${item.asset.id}`}><b>{item.priority}</b><span>{item.label}<small>{item.purpose}</small></span></div>)}</div></details></>}{shot.preparedPrompt&&<details className="fold" open><summary><span>Prompt</span><ChevronDown/></summary><div className="prompt-box"><pre>{shot.preparedPrompt}</pre><button onClick={async()=>{await navigator.clipboard.writeText(shot.preparedPrompt!);toast.success("Prompt copiado");}}><Copy/>Copiar</button></div></details>}<details className="fold"><summary><span>Advanced</span><ChevronDown/></summary><div className="advanced-fields"><label>Camera<input value={shot.camera} onChange={(event)=>updateShot({camera:event.target.value})}/></label><label>Transition<Select value={shot.transitionType} onValueChange={(value)=>updateShot({transitionType:value as TransitionType})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{["AUTO","CUT","CUT_ON_ACTION","REACTION_CUT","MATCH_CUT","CONTINUOUS_TRANSITION","BRIDGE_SHOT"].map((value)=><SelectItem key={value} value={value}>{value.replaceAll("_"," ")}</SelectItem>)}</SelectContent></Select></label><label>Provider<Select value={shot.preferredProvider} onValueChange={(value)=>updateShot({preferredProvider:value})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="vibes">Meta Vibes</SelectItem><SelectItem value="veo">Veo</SelectItem><SelectItem value="generic">Generic</SelectItem></SelectContent></Select></label></div></details>{shot.preparedPrompt&&<div className="generation-actions"><Button onClick={prepareGeneration} disabled={busy}><MonitorPlay/>GENERATE</Button><label><input hidden type="file" accept="video/mp4,video/webm,video/quicktime" onChange={(event)=>{approveVideo(event.target.files?.[0]);event.target.value="";}}/><ShieldCheck/>APPROVE SHOT</label></div>}<GenerationPreflightPanel preflight={generationPreflight} diagnostic={generationDiagnostic}/></aside>;
  if(focusMode)return <div className="workspace focus-workspace">{canvas}</div>;
  let defaultLayout={shots:21,canvas:50,inspector:29};try{defaultLayout=JSON.parse(localStorage.getItem("pd-layout")||JSON.stringify(defaultLayout));}catch{}
  return <div className="workspace"><ResizablePanelGroup orientation="horizontal" defaultLayout={defaultLayout} onLayoutChanged={(layout,meta)=>{if(meta.isUserInteraction)localStorage.setItem("pd-layout",JSON.stringify(layout));}}><ResizablePanel id="shots" minSize="220px" maxSize="300px" defaultSize="270px">{nav}</ResizablePanel><ResizableHandle withHandle/><ResizablePanel id="canvas" minSize="360px">{canvas}</ResizablePanel>{inspectorOpen&&<><ResizableHandle withHandle/><ResizablePanel id="inspector" minSize="300px" maxSize="480px" defaultSize="360px">{inspector}</ResizablePanel></>}</ResizablePanelGroup><button className="reset-layout" onClick={()=>{localStorage.removeItem("pd-layout");location.reload();}}><RotateCcw/>Reset layout</button></div>;
}

function ProjectBible({project,change,uploadFile,tab,setTab,openCharacterId,onCharacterSelect}:{project:Project;change:(patch:Partial<Project>)=>void;uploadFile:(file:File,kind:string)=>Promise<AssetRef>;tab:string;setTab:(tab:string)=>void;openCharacterId?:string;onCharacterSelect:(id:string)=>void}){
  const [selectedId,setSelectedId]=useState<string|null>(null);const [busy,setBusy]=useState("");const selected=project.characters.find((item)=>item.id===selectedId);const active=selected?activeCharacterVersion(selected):undefined;
  useEffect(()=>{if(openCharacterId)setSelectedId(openCharacterId);},[openCharacterId]);
  useEffect(()=>{if(selectedId)onCharacterSelect(selectedId);},[selectedId,onCharacterSelect]);
  function updateCharacter(id:string,patch:Partial<CharacterBible>){change({characters:project.characters.map((item)=>item.id===id?{...item,...patch}:item)});}function updateVersion(character:CharacterBible,versionId:string,patch:Partial<CharacterVersion>){updateCharacter(character.id,{versions:character.versions.map((item)=>item.id===versionId?{...item,...patch}:item)});}function setActiveVersion(character:CharacterBible,versionId:string){updateCharacter(character.id,{activeVersionId:versionId,versions:character.versions.map((item)=>({...item,active:item.id===versionId}))});}
  function addCharacter(){const id=crypto.randomUUID();const versionId=crypto.randomUUID();change({characters:[...project.characters,{id,name:"New character",role:"",age:"",description:"",dominantHand:"",persistentObjects:"",knownFailures:[],activeVersionId:versionId,versions:[{id:versionId,label:"V1",active:true,promptAnchor:"",immutable:"",forbidden:"",references:[]}]}]});setSelectedId(id);onCharacterSelect(id);}
  function addVersion(character:CharacterBible){const base=activeCharacterVersion(character);if(!base)return;const version:CharacterVersion={...base,id:crypto.randomUUID(),label:`V${character.versions.length+1}`,active:true,createdAt:new Date().toISOString(),references:[]};updateCharacter(character.id,{activeVersionId:version.id,versions:[...character.versions.map((item)=>({...item,active:false})),version]});}
  async function addReference(character:CharacterBible,version:CharacterVersion,kind:ReferenceKind,file?:File){if(!file)return;setBusy(`${version.id}-${kind}`);try{const asset=await uploadFile(file,kind);let refs=version.references;if(kind==="OFFICIAL_IDENTITY")refs=refs.map((item)=>item.kind==="OFFICIAL_IDENTITY"?{...item,kind:"ARCHIVE"}:item);updateVersion(character,version.id,{references:[...refs,{...asset,kind}]});toast.success("Referência guardada");}catch(error){toast.error((error as Error).message);}finally{setBusy("");}}
  function addLocation(){const location:LocationBible={id:crypto.randomUUID(),name:"New location",description:"",versions:[{id:crypto.randomUUID(),label:"V1",promptAnchor:"",immutable:"",forbidden:"",references:[]}]};change({locations:[...project.locations,location]});}
  function addProp(){const prop:PropBible={id:crypto.randomUUID(),name:"New prop",description:"",rules:"",status:"ACTIVE"};change({props:[...project.props,prop]});}
  return <main className="bible-page"><div className="bible-page-head"><div><small>{project.title}</small><h1>Project Bible</h1><p>Permanent project memory for characters, locations, props and visual rules.</p></div><div className="bible-stats"><span><b>{project.characters.length}</b>characters</span><span><b>{project.locations.length}</b>locations</span><span><b>{project.props.length}</b>props</span></div></div><Tabs value={tab} onValueChange={setTab}><div className="sticky-tabs"><TabsList className="bible-tabs"><TabsTrigger value="overview">Overview</TabsTrigger><TabsTrigger value="characters">Characters</TabsTrigger><TabsTrigger value="locations">Locations</TabsTrigger><TabsTrigger value="props">Props</TabsTrigger><TabsTrigger value="visual">Visual Style</TabsTrigger><TabsTrigger value="rules">Story Rules</TabsTrigger></TabsList></div><TabsContent value="overview"><div className="overview-grid"><BibleOverviewCard icon={<Users/>} title="Characters" value={project.characters.length} note="Identity locks and active references" onClick={()=>setTab("characters")}/><BibleOverviewCard icon={<MapPinned/>} title="Locations" value={project.locations.length} note="Canonical environments" onClick={()=>setTab("locations")}/><BibleOverviewCard icon={<Boxes/>} title="Props" value={project.props.length} note="Persistent story objects" onClick={()=>setTab("props")}/><BibleOverviewCard icon={<ShieldCheck/>} title="Continuity" value={project.scenes.filter((item)=>item.status==="APPROVED").length} note="Approved canonical shots" onClick={()=>setTab("rules")}/></div></TabsContent><TabsContent value="characters"><div className="content-heading"><div><h2>Characters</h2><p>Official identity and active reference versions.</p></div><Button onClick={addCharacter}><Plus/>Add character</Button></div>{project.characters.length?<div className="character-card-grid">{project.characters.map((character)=>{const version=activeCharacterVersion(character);const official=version?.references.find((asset)=>asset.kind==="OFFICIAL_IDENTITY");return <button className="character-card" key={character.id} onClick={()=>setSelectedId(character.id)}><div>{official?<img src={`/api/assets?id=${official.id}`} alt={character.name}/>:<span>{character.name.slice(0,1)}</span>}<em>{version?.references.length||0} refs</em></div><strong>{character.name}</strong><small>Active {version?.label||"—"} · {character.role||"No role"}</small></button>;})}</div>:<EmptyState icon={<Users/>} title="No characters yet" text="Characters define the visual identity used automatically during video generation." action="Add character" onAction={addCharacter}/>}</TabsContent><TabsContent value="locations"><div className="content-heading"><div><h2>Locations</h2><p>Canonical places and visual constraints.</p></div><Button onClick={addLocation}><Plus/>Add location</Button></div>{project.locations.length?<div className="simple-grid">{project.locations.map((location)=>{const version=location.versions[0];return <article className="simple-card" key={location.id}><MapPinned/><input value={location.name} onChange={(event)=>change({locations:project.locations.map((item)=>item.id===location.id?{...item,name:event.target.value}:item)})}/><textarea placeholder="Architecture, materials, lighting" value={version.promptAnchor} onChange={(event)=>change({locations:project.locations.map((item)=>item.id===location.id?{...item,versions:[{...version,promptAnchor:event.target.value}]}:item)})}/></article>;})}</div>:<EmptyState icon={<MapPinned/>} title="No locations yet" text="Locations preserve architecture, materials and lighting across shots." action="Add location" onAction={addLocation}/>}</TabsContent><TabsContent value="props"><div className="content-heading"><div><h2>Props</h2><p>Objects that must remain consistent through the story.</p></div><Button onClick={addProp}><Plus/>Add prop</Button></div><div className="simple-grid">{project.props.map((prop)=><article className="simple-card" key={prop.id}><Boxes/><input value={prop.name} onChange={(event)=>change({props:project.props.map((item)=>item.id===prop.id?{...item,name:event.target.value}:item)})}/><textarea value={prop.description} placeholder="Description" onChange={(event)=>change({props:project.props.map((item)=>item.id===prop.id?{...item,description:event.target.value}:item)})}/><textarea value={prop.rules} placeholder="Owner, count and continuity rules" onChange={(event)=>change({props:project.props.map((item)=>item.id===prop.id?{...item,rules:event.target.value}:item)})}/><Select value={prop.status} onValueChange={(value)=>change({props:project.props.map((item)=>item.id===prop.id?{...item,status:value as PropBible["status"]}:item)})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="ACTIVE">ACTIVE</SelectItem><SelectItem value="INACTIVE">INACTIVE</SelectItem></SelectContent></Select></article>)}</div></TabsContent><TabsContent value="visual"><div className="rule-editor"><label>Visual style<textarea value={project.style} onChange={(event)=>change({style:event.target.value})}/></label><label>Never use<textarea value={project.styleNegative} onChange={(event)=>change({styleNegative:event.target.value})}/></label></div></TabsContent><TabsContent value="rules"><div className="rule-editor"><label>Story rules<textarea value={project.storyRules} onChange={(event)=>change({storyRules:event.target.value})}/></label><label>Continuity rules<textarea value={project.continuityRules} onChange={(event)=>change({continuityRules:event.target.value})}/></label><label>Lovable project URL<input value={project.url} onChange={(event)=>change({url:event.target.value})} placeholder="https://lovable.dev/projects/…"/></label></div></TabsContent></Tabs><Sheet open={Boolean(selected&&active)} onOpenChange={(open)=>!open&&setSelectedId(null)}>{selected&&active&&<SheetContent className="character-sheet"><SheetHeader><SheetTitle>{selected.name}</SheetTitle><SheetDescription>Official identity, active version and reference library.</SheetDescription></SheetHeader><div className="sheet-body"><div className="character-title"><div><small>ACTIVE VERSION: {active.label}</small><input value={selected.name} onChange={(event)=>updateCharacter(selected.id,{name:event.target.value})}/></div><div><Select value={active.id} onValueChange={(value)=>setActiveVersion(selected,value)}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{selected.versions.map((version)=><SelectItem key={version.id} value={version.id}>{version.label}{version.id===selected.activeVersionId?" · ACTIVE":" · archived"}</SelectItem>)}</SelectContent></Select><Button variant="outline" onClick={()=>addVersion(selected)}><Plus/>New version</Button></div></div><div className="identity-fields"><label>Age<input value={selected.age||""} onChange={(event)=>updateCharacter(selected.id,{age:event.target.value})}/></label><label>Role<input value={selected.role} onChange={(event)=>updateCharacter(selected.id,{role:event.target.value})}/></label><label>Dominant hand<input value={selected.dominantHand||""} onChange={(event)=>updateCharacter(selected.id,{dominantHand:event.target.value})}/></label><label>Persistent objects<input value={selected.persistentObjects||""} onChange={(event)=>updateCharacter(selected.id,{persistentObjects:event.target.value})}/></label><label className="wide">Visual<textarea value={active.promptAnchor} onChange={(event)=>updateVersion(selected,active.id,{promptAnchor:event.target.value})}/></label><label className="wide">Critical rules<textarea value={active.immutable} onChange={(event)=>updateVersion(selected,active.id,{immutable:event.target.value})}/></label><label className="wide">Never<textarea value={active.forbidden} onChange={(event)=>updateVersion(selected,active.id,{forbidden:event.target.value})}/></label></div><div className="reference-library">{referenceGroups.map((group)=>{const assets=active.references.filter((asset)=>asset.kind===group.kind);return <section key={group.kind}><div><span>{group.kind==="OFFICIAL_IDENTITY"&&<Star/>}{group.label}</span><small>{group.hint}</small></div><div className="reference-grid">{assets.map((asset)=><figure key={asset.id}><img src={`/api/assets?id=${asset.id}`} alt={asset.name}/><figcaption>{asset.name}</figcaption></figure>)}<label className="add-reference"><input hidden type="file" accept="image/*" onChange={(event)=>{addReference(selected,active,group.kind,event.target.files?.[0]);event.target.value="";}}/>{busy===`${active.id}-${group.kind}`?<Loader2 className="spin"/>:<ImagePlus/>}<span>Add image</span></label></div></section>;})}</div><div className="failure-memory"><b>Known generation problems</b><textarea value={(selected.knownFailures||[]).join("\n")} onChange={(event)=>updateCharacter(selected.id,{knownFailures:event.target.value.split("\n").filter(Boolean)})}/></div></div></SheetContent>}</Sheet></main>;
}

function EmptyState({icon,title,text,action,onAction}:{icon:React.ReactNode;title:string;text:string;action:string;onAction:()=>void}){return <div className="empty-state">{icon}<h3>{title}</h3><p>{text}</p><Button onClick={onAction}><Plus/>{action}</Button></div>;}
function BibleOverviewCard({icon,title,value,note,onClick}:{icon:React.ReactNode;title:string;value:number;note:string;onClick:()=>void}){return <button className="overview-card" onClick={onClick}><span>{icon}</span><div><small>{title}</small><strong>{value}</strong><p>{note}</p></div><ArrowRight/></button>;}
function StatusMark({status}:{status:Shot["status"]}){if(status==="APPROVED")return <CheckCircle2 className="approved-mark"/>;if(status==="REJECTED")return <XCircle className="rejected-mark"/>;return <span className="pending-mark"/>;}
function UploadCard({title,asset,empty,note,onClick}:{title:string;asset?:AssetRef|null;empty:string;note?:string;onClick:()=>void}){return <button className={asset?"media-card filled":"media-card"} onClick={onClick}><div className="media-card-head"><span>{title}</span>{asset?<CheckCircle2/>:<ImagePlus/>}</div><div className="media-preview">{asset?<img src={`/api/assets?id=${asset.id}`} alt={asset.name}/>:<><ImagePlus/><span>{empty}</span></>}</div>{note&&<small>{note}</small>}</button>;}
function MediaCard({title,asset,sourceUrl,kind,empty}:{title:string;asset?:AssetRef;sourceUrl?:string;kind:"video"|"image";empty:string}){const source=asset?`/api/assets?id=${asset.id}`:sourceUrl;return <div className={source?"media-card filled":"media-card"}><div className="media-card-head"><span>{title}</span><Film/></div><div className="media-preview">{source?(kind==="video"?<video controls src={source}/>:<img src={source} alt={asset?.name||title}/>):<><MonitorPlay/><span>{empty}</span></>}</div></div>;}
function AnalysisPanel({analysis}:{analysis:ContinuityAnalysis}){return <div className="compact-analysis"><div className="score"><strong>{analysis.score}%</strong><span>{analysis.transition.replaceAll("_"," ")}</span></div>{analysis.critical.map((item)=><p className="critical" key={item}><AlertTriangle/>{item}</p>)}{analysis.warnings.map((item)=><p className="warning" key={item}><AlertTriangle/>{item}</p>)}{analysis.checks.slice(0,3).map((item)=><p key={item}><CheckCircle2/>{item}</p>)}<small>{analysis.transitionReason}</small></div>;}
function GenerationPreflightPanel({preflight,diagnostic}:{preflight?:GenerationPreflight;diagnostic?:unknown}){if(!preflight&&!diagnostic)return null;return <section className={`generation-preflight ${preflight?.ready?"ready":"invalid"}`}><strong>{preflight?.ready?"READY TO GENERATE":"Generation package invalid"}</strong>{preflight?.checks.map((item)=><span key={item.label} className={item.ok?"ok":"bad"}>{item.ok?"✓":"×"} {item.label}{item.value?`: ${item.value}`:""}</span>)}{preflight?.warnings.map((item)=><p key={item}><AlertTriangle/> {item}</p>)}{Boolean(preflight?.missing.length)&&<div><b>Missing</b>{preflight!.missing.map((item)=><small key={item}>{item}</small>)}</div>}{Boolean(preflight?.invalid.length)&&<div><b>Invalid</b>{preflight!.invalid.map((item)=><small key={item}>{item}</small>)}</div>}{Boolean(preflight?.unresolvedAssets.length)&&<div><b>Unresolved assets</b>{preflight!.unresolvedAssets.map((item)=><small key={item}>{item}</small>)}</div>}{Boolean(diagnostic)&&<button onClick={async()=>{await navigator.clipboard.writeText(JSON.stringify(diagnostic,null,2));toast.success("Diagnóstico copiado");}}><Copy/>Copy diagnostic</button>}</section>;}

type ProviderInfo={id:string;name:string;model?:string;configured:boolean;status:string;mode?:string;detail?:string;projectUrl?:string};
function ProviderSettingsSheet({open,onClose}:{open:boolean;onClose:()=>void}){
  const [data,setData]=useState<{ai:ProviderInfo[];video:ProviderInfo[]}>({ai:[],video:[]});
  const [testing,setTesting]=useState("");
  const [extensionId,setExtensionId]=useState("");
  const [bridgeState,setBridgeState]=useState<BridgeStatus>("disconnected");
  const [bridgeVersion,setBridgeVersion]=useState("2.0.0");
  const [bridgeConnection,setBridgeConnection]=useState<"automatic"|"extension_id">();
  const [bridgeDiagnostic,setBridgeDiagnostic]=useState<BridgeDiagnostic>();
  useEffect(()=>{if(open){const savedId=configuredExtensionId();setExtensionId(savedId);request<{ai:ProviderInfo[];video:ProviderInfo[]}>("/api/providers").then(setData).catch(()=>toast.error("Não foi possível carregar os providers."));testBrowserBridge(savedId).then((result)=>{setBridgeState(result.ok?"ready":"disconnected");setBridgeConnection(result.connection);setBridgeDiagnostic(result.diagnostic);if(result.version)setBridgeVersion(result.version);});}},[open]);
  async function test(id:string){setTesting(id);try{await request("/api/providers",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({provider:id})});toast.success(`${id} conectado`);}catch(error){toast.error((error as Error).message);}finally{setTesting("");}}
  function saveBridgeId(){saveExtensionId(extensionId);toast.success(extensionId.trim()?"Extension ID guardado.":"Extension ID removido.");}
  async function testBridge(){setTesting("bridge");const result=await testBrowserBridge(extensionId.trim());setBridgeState(result.ok?"ready":"disconnected");setBridgeConnection(result.connection);setBridgeDiagnostic(result.diagnostic);if(result.version)setBridgeVersion(result.version);if(result.ok)toast.success(result.connection==="extension_id"?"Connected via Extension ID":"Connected automatically");else toast.error("PromptDirector Bridge not detected.");setTesting("");}
  return <Sheet open={open} onOpenChange={(value)=>!value&&onClose()}><SheetContent className="provider-sheet"><SheetHeader><SheetTitle>Providers</SheetTitle><SheetDescription>Real connection status for analysis and video generation.</SheetDescription></SheetHeader><div className="provider-list"><h3>AI</h3>{data.ai.map((item)=><article key={item.id}><div><b>{item.name}</b><small>{item.model}</small></div><span className={item.configured?"connected":"not-configured"}>{item.status.replaceAll("_"," ")}</span><Button variant="outline" disabled={testing===item.id} onClick={()=>test(item.id)}>{testing===item.id?<Loader2 className="spin"/>:"Test connection"}</Button></article>)}<h3>Video</h3><article className="bridge-settings"><div><b>PromptDirector Bridge</b><small>Version: {bridgeVersion}</small>{bridgeState==="ready"&&<small>{bridgeConnection==="extension_id"?"Connected via Extension ID":"Connected automatically"}</small>}</div><span className={bridgeState==="ready"?"connected":"not-configured"}>{bridgeState==="ready"?"Connected":"Disconnected"}</span><label>Extension ID<input value={extensionId} onChange={(event)=>setExtensionId(event.target.value)} placeholder="Cole o ID da extensão Chrome" autoComplete="off"/></label><div className="bridge-buttons"><Button variant="outline" onClick={saveBridgeId}>SAVE</Button><Button variant="outline" disabled={testing==="bridge"} onClick={testBridge}>{testing==="bridge"?<Loader2 className="spin"/>:"TEST BRIDGE"}</Button></div>{bridgeDiagnostic&&<dl className="bridge-diagnostic"><dt>Auto Discovery</dt><dd>{bridgeDiagnostic.autoDiscovery}</dd><dt>Extension ID</dt><dd>{bridgeDiagnostic.extensionId}</dd><dt>Direct Ping</dt><dd>{bridgeDiagnostic.directPing}</dd><dt>Bridge Version</dt><dd>{bridgeDiagnostic.bridgeVersion}</dd><dt>Status</dt><dd>{bridgeDiagnostic.status}</dd></dl>}<a href="https://vibes.ai/projects/40c14372-cf55-4a4c-ba23-bdb454c9fb85" target="_blank" rel="noreferrer">Open Vibes</a></article>{data.video.filter((item)=>item.id!=="vibes").map((item)=><article key={item.id}><div><b>{item.name}</b><small>{item.mode||item.detail}</small></div><span className={item.configured?"connected":"not-configured"}>{item.status.replaceAll("_"," ")}</span><Button variant="outline" disabled>Not configured</Button><p>{item.detail}</p></article>)}</div></SheetContent></Sheet>;
}
